package transport

import (
	"bytes"
	"compress/gzip"
	cryptorand "crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"errors"
	"fmt"
	"io"
	"math/big"
	"strings"
	"sync"
)

const (
	duckDuckGoTextUserAgentRowsSHA256 = "e36a0c36f109eecf4bda3c835d57f0e5ddd72f77591c6a3442179d9c2f244475"
	duckDuckGoTextUserAgentPoolData   = ``
)

var (
	duckDuckGoTextUserAgentPoolOnce = sync.OnceValues(loadDuckDuckGoTextUserAgentPool)
	duckDuckGoTextUserAgentOnce     = sync.OnceValues(newDuckDuckGoTextUserAgent)
)

// DuckDuckGoTextUserAgent returns the source-compatible process-lifetime
// User-Agent selected for DuckDuckGo text transport construction.
func DuckDuckGoTextUserAgent() (string, error) {
	return duckDuckGoTextUserAgentOnce()
}

func newDuckDuckGoTextUserAgent() (string, error) {
	pool, err := duckDuckGoTextUserAgentPool()
	if err != nil {
		return "", err
	}
	return newDuckDuckGoTextUserAgentPicker(pool, duckDuckGoTextRandomIndex)()
}

func duckDuckGoTextUserAgentPool() ([]string, error) {
	return duckDuckGoTextUserAgentPoolOnce()
}

func loadDuckDuckGoTextUserAgentPool() ([]string, error) {
	compressed, err := base64.StdEncoding.DecodeString(duckDuckGoTextUserAgentPoolData)
	if err != nil {
		return nil, fmt.Errorf("decode DuckDuckGo user-agent asset: %w", err)
	}
	reader, err := gzip.NewReader(bytes.NewReader(compressed))
	if err != nil {
		return nil, fmt.Errorf("open DuckDuckGo user-agent asset: %w", err)
	}
	decompressed, readErr := io.ReadAll(reader)
	closeErr := reader.Close()
	if readErr != nil {
		return nil, fmt.Errorf("read DuckDuckGo user-agent asset: %w", readErr)
	}
	if closeErr != nil {
		return nil, fmt.Errorf("close DuckDuckGo user-agent asset: %w", closeErr)
	}
	sum := sha256.Sum256(decompressed)
	if fmt.Sprintf("%x", sum) != duckDuckGoTextUserAgentRowsSHA256 {
		return nil, errors.New("DuckDuckGo user-agent asset checksum mismatch")
	}
	if len(decompressed) == 0 || decompressed[len(decompressed)-1] != '\n' {
		return nil, errors.New("DuckDuckGo user-agent asset is not newline terminated")
	}
	pool := strings.Split(string(decompressed[:len(decompressed)-1]), "\n")
	if len(pool) == 0 || pool[0] == "" {
		return nil, errors.New("DuckDuckGo user-agent asset has no entries")
	}
	return pool, nil
}

func newDuckDuckGoTextUserAgentPicker(pool []string, randomIndex func(int) (int, error)) func() (string, error) {
	return func() (string, error) {
		if len(pool) == 0 {
			return "", errors.New("DuckDuckGo user-agent pool is empty")
		}
		index, err := randomIndex(len(pool))
		if err != nil {
			return "", fmt.Errorf("select DuckDuckGo user agent: %w", err)
		}
		if index < 0 || index >= len(pool) {
			return "", fmt.Errorf("DuckDuckGo user-agent index %d out of range", index)
		}
		return pool[index], nil
	}
}

func duckDuckGoTextRandomIndex(limit int) (int, error) {
	if limit <= 0 {
		return 0, errors.New("DuckDuckGo user-agent random limit must be positive")
	}
	value, err := cryptorand.Int(cryptorand.Reader, big.NewInt(int64(limit)))
	if err != nil {
		return 0, err
	}
	return int(value.Int64()), nil
}
